-- A) RESUMEN por migración (SOLO LECTURA). Esquema explícito: bkwlgxt1ccjstm5cfoy5
SELECT mig, presentes, esperados,
       CASE WHEN presentes >= esperados THEN 'COMPLETA' WHEN presentes = 0 THEN 'AUSENTE' ELSE 'PARCIAL' END AS estado
FROM (
  SELECT '03' AS mig, 10 AS esperados,
    (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_usuarios' AND COLUMN_NAME = 'token_version')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_custodios' AND COLUMN_NAME = 'departamento')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_custodios' AND COLUMN_NAME = 'telefono')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_almacenes' AND COLUMN_NAME = 'estado_verificacion')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_almacenes' AND COLUMN_NAME = 'origen_registro')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_articulos' AND COLUMN_NAME = 'area' AND COLUMN_TYPE LIKE '%''OTRA''%')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_articulos' AND COLUMN_NAME = 'cantidad_num' AND COLUMN_TYPE = 'decimal(12,2)')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_articulos' AND COLUMN_NAME = 'estado_vinculacion_sede' AND COLUMN_TYPE LIKE '%''SIN_VINCULAR''%')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamentos' AND COLUMN_NAME = 'clasificacion_sede' AND COLUMN_TYPE LIKE '%''PENDIENTE_VALIDACION''%')
    + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_levantamientos' AND COLUMN_NAME = 'estado' AND COLUMN_TYPE LIKE '%''Cancelado''%') AS presentes
  UNION ALL SELECT '04', 5,
    (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamento_alias')
    + (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamento_alias' AND INDEX_NAME IN ('idx_alias_camp', 'idx_alias_codigo', 'uk_alias_normalizado'))
    + (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamento_alias' AND CONSTRAINT_NAME = 'fk_alias_campamento')
  UNION ALL SELECT '06', 21,
    (SELECT COUNT(*) FROM (SELECT DISTINCT TABLE_NAME, INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5') i WHERE (TABLE_NAME, INDEX_NAME) IN (('inv_articulos','idx_art_campamento'),('inv_articulos','idx_art_almacen'),('inv_articulos','idx_art_filtro_compuesto'),('inv_movimientos','idx_mov_sint_fecha')))
    + (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND CONSTRAINT_TYPE = 'FOREIGN KEY' AND CONSTRAINT_NAME IN ('fk_mov_articulo', 'fk_mov_usuario', 'fk_art_lote', 'fk_art_creado_por', 'fk_lote_usuario', 'fk_aud_usuario', 'fk_lev_campamento', 'fk_lev_almacen', 'fk_lev_consolidado_por', 'fk_lev_creado_por', 'fk_item_levantamiento', 'fk_item_maestro', 'fk_item_creado_por', 'fk_usr_campamento', 'fk_usr_almacen', 'fk_uc_usuario', 'fk_uc_campamento', 'fk_ua_usuario', 'fk_ua_almacen'))
) r;

-- B) DETALLE por indicador (solo si A muestra PARCIAL). valor 1 = presente, 0 = ausente. SOLO LECTURA.
SELECT '03' AS mig, 'inv_usuarios.token_version' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_usuarios' AND COLUMN_NAME = 'token_version') AS valor
UNION ALL SELECT '03' AS mig, 'inv_custodios.departamento' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_custodios' AND COLUMN_NAME = 'departamento') AS valor
UNION ALL SELECT '03' AS mig, 'inv_custodios.telefono' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_custodios' AND COLUMN_NAME = 'telefono') AS valor
UNION ALL SELECT '03' AS mig, 'inv_almacenes.estado_verificacion' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_almacenes' AND COLUMN_NAME = 'estado_verificacion') AS valor
UNION ALL SELECT '03' AS mig, 'inv_almacenes.origen_registro' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_almacenes' AND COLUMN_NAME = 'origen_registro') AS valor
UNION ALL SELECT '03' AS mig, 'inv_articulos.area incluye ''OTRA''' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_articulos' AND COLUMN_NAME = 'area' AND COLUMN_TYPE LIKE '%''OTRA''%') AS valor
UNION ALL SELECT '03' AS mig, 'inv_articulos.cantidad_num = decimal(12,2)' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_articulos' AND COLUMN_NAME = 'cantidad_num' AND COLUMN_TYPE = 'decimal(12,2)') AS valor
UNION ALL SELECT '03' AS mig, 'inv_articulos.estado_vinculacion_sede incluye ''SIN_VINCULAR''' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_articulos' AND COLUMN_NAME = 'estado_vinculacion_sede' AND COLUMN_TYPE LIKE '%''SIN_VINCULAR''%') AS valor
UNION ALL SELECT '03' AS mig, 'inv_campamentos.clasificacion_sede incluye ''PENDIENTE_VALIDACION''' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamentos' AND COLUMN_NAME = 'clasificacion_sede' AND COLUMN_TYPE LIKE '%''PENDIENTE_VALIDACION''%') AS valor
UNION ALL SELECT '03' AS mig, 'inv_levantamientos.estado incluye ''Cancelado''' AS indicador, (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_levantamientos' AND COLUMN_NAME = 'estado' AND COLUMN_TYPE LIKE '%''Cancelado''%') AS valor
UNION ALL SELECT '04' AS mig, 'tabla inv_campamento_alias' AS indicador, (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamento_alias') AS valor
UNION ALL SELECT '04' AS mig, '3 indices del alias (idx_alias_camp, idx_alias_codigo, uk_alias_normalizado)' AS indicador, (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamento_alias' AND INDEX_NAME IN ('idx_alias_camp', 'idx_alias_codigo', 'uk_alias_normalizado')) AS valor
UNION ALL SELECT '04' AS mig, 'FK fk_alias_campamento' AS indicador, (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND TABLE_NAME = 'inv_campamento_alias' AND CONSTRAINT_NAME = 'fk_alias_campamento') AS valor
UNION ALL SELECT '06' AS mig, 'indices de la 06 presentes (de 4)' AS indicador, (SELECT COUNT(*) FROM (SELECT DISTINCT TABLE_NAME, INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5') i WHERE (TABLE_NAME, INDEX_NAME) IN (('inv_articulos','idx_art_campamento'),('inv_articulos','idx_art_almacen'),('inv_articulos','idx_art_filtro_compuesto'),('inv_movimientos','idx_mov_sint_fecha'))) AS valor
UNION ALL SELECT '06' AS mig, 'claves foraneas fk_* de la 06 presentes (de 19; 17 es normal)' AS indicador, (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = 'bkwlgxt1ccjstm5cfoy5' AND CONSTRAINT_TYPE = 'FOREIGN KEY' AND CONSTRAINT_NAME IN ('fk_mov_articulo', 'fk_mov_usuario', 'fk_art_lote', 'fk_art_creado_por', 'fk_lote_usuario', 'fk_aud_usuario', 'fk_lev_campamento', 'fk_lev_almacen', 'fk_lev_consolidado_por', 'fk_lev_creado_por', 'fk_item_levantamiento', 'fk_item_maestro', 'fk_item_creado_por', 'fk_usr_campamento', 'fk_usr_almacen', 'fk_uc_usuario', 'fk_uc_campamento', 'fk_ua_usuario', 'fk_ua_almacen')) AS valor;
